import pytest
from target import solution


def test_example_1():
    assert solution([5, 8, 7, 1]) == 12


def test_example_2():
    assert solution([3, 3, 3, 3, 3]) == 9


def test_example_3():
    assert solution([30, 13, 24, 321]) == 0


def test_single_element_odd():
    # position 0 is even, element is odd -> included
    assert solution([7]) == 7


def test_single_element_even():
    # position 0 is even, element is even -> not included
    assert solution([4]) == 0


def test_two_elements_only_first_counted():
    # position 1 (odd index) should be excluded even if odd
    assert solution([3, 5]) == 3


def test_two_elements_first_even():
    assert solution([4, 5]) == 0


def test_negative_odd_numbers_at_even_positions():
    # positions 0,2 -> -3, -5 both odd -> sum = -8
    assert solution([-3, 2, -5, 4]) == -8


def test_negative_even_numbers_at_even_positions():
    assert solution([-4, 3, -6, 5]) == 0


def test_all_even_positions_even_values():
    assert solution([2, 1, 4, 3, 6, 5]) == 0


def test_all_even_positions_odd_values():
    assert solution([1, 2, 3, 4, 5, 6]) == 9


def test_zero_at_even_position_not_odd():
    # zero is even, should not be counted
    assert solution([0, 1, 0, 1]) == 0


def test_mixed_signs_and_values():
    # positions: 0=-1(odd),1=10,2=7(odd),3=-8,4=0,5=3
    assert solution([-1, 10, 7, -8, 0, 3]) == 6

from target import simplify


def test_example_1():
    assert simplify("1/5", "5/1") is True


def test_example_2():
    assert simplify("1/6", "2/1") is False


def test_example_3():
    assert simplify("7/10", "10/2") is False


def test_simple_whole_number():
    assert simplify("1/2", "2/1") is True


def test_simple_non_whole_number():
    assert simplify("1/3", "2/1") is False


def test_identity_one_over_one():
    assert simplify("1/1", "1/1") is True


def test_large_numbers_whole():
    assert simplify("3/7", "14/3") is True


def test_large_numbers_non_whole():
    assert simplify("3/7", "14/5") is False


def test_numerator_equals_denominator_other():
    assert simplify("5/5", "3/3") is True


def test_both_fractions_reduce_to_whole():
    assert simplify("4/6", "3/2") is True


def test_result_less_than_one():
    assert simplify("1/10", "1/1") is False


def test_result_exactly_one():
    assert simplify("2/3", "3/2") is True


def test_numerator_one_denominator_large():
    assert simplify("1/100", "100/1") is True


def test_denominator_does_not_cancel():
    assert simplify("1/100", "99/1") is False


def test_both_numerators_one():
    assert simplify("1/4", "1/4") is False


def test_cross_reduction_needed():
    assert simplify("2/4", "4/2") is True


def test_return_type_is_bool_true():
    result = simplify("1/5", "5/1")
    assert isinstance(result, bool)


def test_return_type_is_bool_false():
    result = simplify("1/6", "2/1") 
    assert isinstance(result, bool)

import pytest
from target import match_parens


def test_empty_strings():
    """Both strings empty - balanced"""
    assert match_parens(['', '']) == 'Yes'


def test_one_empty_other_balanced():
    """One empty, other already balanced"""
    assert match_parens(['', '()']) == 'Yes'
    assert match_parens(['()', '']) == 'Yes'


def test_one_empty_other_single_open():
    """One empty, other unbalanced with single open"""
    assert match_parens(['', '(']) == 'No'
    assert match_parens(['(', '']) == 'No'


def test_one_empty_other_single_close():
    """One empty, other unbalanced with single close"""
    assert match_parens(['', ')']) == 'No'
    assert match_parens([')', '']) == 'No'


def test_single_open_single_close():
    """Single open and close in either order"""
    assert match_parens(['(', ')']) == 'Yes'
    assert match_parens([')', '(']) == 'Yes'


def test_two_opens():
    """Two opens cannot be balanced"""
    assert match_parens(['(', '(']) == 'No'


def test_two_closes():
    """Two closes cannot be balanced"""
    assert match_parens([')', ')']) == 'No'


def test_docstring_example_1():
    """First example from docstring"""
    assert match_parens(['()(', ')']) == 'Yes'


def test_docstring_example_2():
    """Second example from docstring"""
    assert match_parens([')', ')']) == 'No'


def test_order_matters_opens_before_closes():
    """Works when opens come before closes"""
    assert match_parens(['((', '))']) == 'Yes'


def test_both_orders_fail():
    """Neither concatenation order produces balanced string"""
    assert match_parens([')(', '()']) == 'No'


def test_three_opens_two_closes():
    """Both have balanced counts"""
    assert match_parens(['(()', ')()']) == 'Yes'


def test_both_already_balanced():
    """Both strings individually balanced"""
    assert match_parens(['()', '()']) == 'Yes'


def test_many_opens_then_many_closes():
    """Four opens concatenated with four closes"""
    assert match_parens(['((((', '))))']) == 'Yes'


def test_longer_with_internal_balance():
    """Longer strings with internal balance checks"""
    assert match_parens(['(())', '()']) == 'Yes'


def test_imbalanced_distributions():
    """First string has excess closes, second has excess opens"""
    assert match_parens(['(', '())']) == 'Yes'


def test_all_closes_then_all_opens():
    """All closes in first string, all opens in second"""
    assert match_parens(['((', '))']) == 'Yes'


def test_mixed_pattern_1():
    """Complex mixed pattern that requires correct order"""
    assert match_parens(['()()', '(())']) == 'Yes'


def test_unbalanced_total_more_opens():
    """Total has more opens than closes"""
    assert match_parens(['(', '(']) == 'No'


def test_unbalanced_total_more_closes():
    """Total has more closes than opens"""
    assert match_parens([')', ')']) == 'No'

import pytest
from target import sum_squares


# ==================== BOUNDARY: EMPTY AND SINGLE ELEMENT ====================

def test_empty_list():
    """Empty list boundary (base case)"""
    assert sum_squares([]) == 0


def test_single_element_at_index_0_squared():
    """Single element at index 0, must square"""
    assert sum_squares([5]) == 25


def test_single_zero_element():
    """Single zero element"""
    assert sum_squares([0]) == 0


def test_single_negative_at_index_0_squared():
    """Single negative at index 0, squared correctly"""
    assert sum_squares([-3]) == 9


# ==================== BOUNDARY: INDEX SQUARE POSITIONS (i % 3 == 0) ====================

def test_index_0_square():
    """Index 0 square: 7^2 + 10 + 20"""
    assert sum_squares([7, 10, 20]) == 79


def test_index_3_square():
    """Index 3 square: 1 + 2 + 3 + 5^2 = 1+2+3+25"""
    assert sum_squares([1, 2, 3, 5]) == 31


def test_index_6_square():
    """Index 6 square: 0+0+0+0+0+0+4^2"""
    assert sum_squares([0, 0, 0, 0, 0, 0, 4]) == 16


def test_index_9_square():
    """Index 9 square: nine 0s then 3^2"""
    assert sum_squares([0]*9 + [3]) == 9


def test_index_0_negative_squared():
    """Index 0 negative: (-4)^2 + 10 + 20"""
    assert sum_squares([-4, 10, 20]) == 46


def test_index_3_negative_squared():
    """Index 3 negative: 1 + 2 + 3 + (-5)^2"""
    assert sum_squares([1, 2, 3, -5]) == 31


# ==================== BOUNDARY: INDEX CUBE POSITIONS (i % 4 == 0 AND i % 3 != 0) ====================

def test_index_4_cube():
    """Index 4 cube: 1^2 + 2 + 3 + 4^2 + 5^3"""
    assert sum_squares([1, 2, 3, 4, 5]) == 147


def test_index_8_cube():
    """Index 8 cube: eight 0s then 3^3 = 27"""
    assert sum_squares([0]*8 + [3]) == 27


def test_index_16_cube():
    """Index 16 cube: sixteen 0s then 2^3 = 8"""
    assert sum_squares([0]*16 + [2]) == 8


def test_index_4_negative_cubed():
    """Index 4 negative: 1 + 2 + 3 + 16 + (-125)"""
    assert sum_squares([1, 2, 3, 4, -5]) == -93


def test_index_4_negative_cube_only():
    """Index 4 negative cube: (-2)^3 = -8"""
    assert sum_squares([0, 0, 0, 0, -2]) == -8


# ==================== BOUNDARY: UNCHANGED POSITIONS ====================

def test_index_1_unchanged():
    """Index 1 unchanged: 10^2 + 5"""
    assert sum_squares([10, 5]) == 105


def test_index_2_unchanged():
    """Index 2 unchanged: 1 + 2 + 7"""
    assert sum_squares([1, 2, 7]) == 10


def test_index_5_unchanged():
    """Index 5 unchanged: 1 + 2 + 3 + 16 + 125 + 10"""
    assert sum_squares([1, 2, 3, 4, 5, 10]) == 157


def test_index_7_unchanged():
    """Index 7 unchanged: 8"""
    assert sum_squares([0]*7 + [8]) == 8


def test_index_10_unchanged():
    """Index 10 unchanged: 5"""
    assert sum_squares([0]*10 + [5]) == 5


def test_index_11_unchanged():
    """Index 11 unchanged: 6"""
    assert sum_squares([0]*11 + [6]) == 6


# ==================== BOUNDARY: LCM(3,4)=12 INTERACTION ====================

def test_index_12_square_precedence_over_cube():
    """Index 12: both conditions true, square takes precedence (not cube)"""
    assert sum_squares([0]*12 + [5]) == 25


def test_index_12_negative_square_precedence():
    """Index 12 negative: square precedence over cube"""
    assert sum_squares([0]*12 + [-3]) == 9


def test_index_0_and_4_interaction():
    """Index 0 vs 4: 5^2 + 5^3 = 25 + 125"""
    assert sum_squares([5, 0, 0, 0, 5]) == 150


# ==================== EQUIVALENCE CLASS: ALL ZEROS ====================

def test_all_zeros_small():
    """All zeros (identity)"""
    assert sum_squares([0, 0, 0, 0, 0]) == 0


def test_all_zeros_lcm_boundary():
    """All zeros with LCM boundary"""
    assert sum_squares([0]*13) == 0


# ==================== EQUIVALENCE CLASS: ALL POSITIVE ====================

def test_all_positive_simple():
    """All positive, simple (docstring example)"""
    assert sum_squares([1, 2, 3]) == 6


def test_all_positive_with_operations():
    """All positive: 1+2+3+16+125"""
    assert sum_squares([1, 2, 3, 4, 5]) == 147


def test_all_positive_large_values():
    """All positive large: 100+20+30"""
    assert sum_squares([10, 20, 30]) == 150


def test_all_positive_full_cycle():
    """All positive 1-12: full cycle covering all index types"""
    assert sum_squares(list(range(1, 13))) == 1062


# ==================== EQUIVALENCE CLASS: ALL NEGATIVE ====================

def test_single_negative_squared():
    """Single negative: (-5)^2 = 25"""
    assert sum_squares([-5]) == 25


def test_all_negative_values():
    """All negative: 4 + (-4) + (-6) + 64"""
    assert sum_squares([-2, -4, -6, -8]) == 58


def test_mixed_with_negative_at_cube():
    """Negative at cube position: 1+2+3+16+(-125)"""
    assert sum_squares([1, 2, 3, 4, -5]) == -93


def test_negative_cubed():
    """Negative cube: (-3)^3 = -27"""
    assert sum_squares([0, 0, 0, 0, -3]) == -27


# ==================== EQUIVALENCE CLASS: MIXED SIGNS ====================

def test_mixed_positive_negative_signs():
    """Mixed signs: 4 + (-3) + 4 + 25 + 216"""
    assert sum_squares([2, -3, 4, -5, 6]) == 246


def test_complex_mixed_from_docstring():
    """Complex mixed (docstring example)"""
    assert sum_squares([-1, -5, 2, -1, -5]) == -126


# ==================== COUNTEREXAMPLE: CATCHES NAIVE BUGS ====================

def test_counterexample_or_bug():
    """Catches OR bug: index 4 must cube (125) not square (25)"""
    assert sum_squares([1, 1, 1, 1, 5]) == 129


def test_counterexample_precedence_bug():
    """Catches precedence bug: index 12 square not cube"""
    assert sum_squares([0]*12 + [5]) == 25


# ==================== DOCSTRING EXAMPLES ====================

def test_docstring_example_1():
    """For lst = [1,2,3] the output should be 6"""
    assert sum_squares([1, 2, 3]) == 6


def test_docstring_example_2():
    """For lst = []  the output should be 0"""
    assert sum_squares([]) == 0


def test_docstring_example_3():
    """For lst = [-1,-5,2,-1,-5]  the output should be -126"""
    assert sum_squares([-1, -5, 2, -1, -5]) == -126


# ==================== INTEGRATION: COMPREHENSIVE MULTI-OPERATION ====================

def test_four_elements():
    """Four elements: 4 + 3 + 4 + 25"""
    assert sum_squares([2, 3, 4, 5]) == 36


def test_six_elements():
    """Six elements: 1 + 2 + 3 + 16 + 125 + 6"""
    assert sum_squares([1, 2, 3, 4, 5, 6]) == 153


def test_eight_elements():
    """Eight elements: 8 ones + 3^3"""
    assert sum_squares([1]*8 + [3]) == 35


def test_thirteen_elements():
    """Thirteen elements: 11 ones + 5^2"""
    assert sum_squares([1]*12 + [5]) == 36


# ==================== EDGE CASES: LARGE VALUES ====================

def test_large_positive_squared():
    """Large positive: 100^2"""
    assert sum_squares([100]) == 10000


def test_large_negative_squared():
    """Large negative: (-100)^2"""
    assert sum_squares([-100]) == 10000


def test_large_positive_cubed():
    """Large positive cubed: 10^3"""
    assert sum_squares([0, 0, 0, 0, 10]) == 1000


def test_large_negative_cubed():
    """Large negative cubed: (-10)^3"""
    assert sum_squares([0, 0, 0, 0, -10]) == -1000


def test_mixed_zeros_and_ones():
    """Mixed zeros and ones: 1+1"""
    assert sum_squares([1, 0, 0, 1, 0]) == 2

import pytest
from target import match_parens


def test_example_1():
    assert match_parens(['()(', ')']) == 'Yes'


def test_example_2():
    assert match_parens([')', ')']) == 'No'


def test_both_empty_strings():
    assert match_parens(['', '']) == 'Yes'


def test_empty_and_balanced():
    assert match_parens(['', '()']) == 'Yes'


def test_empty_and_unbalanced_reversed_order():
    # ')(' alone is never balanced, and concatenating with '' doesn't help
    assert match_parens(['', ')(']) == 'No'


def test_simple_open_close_pair():
    assert match_parens(['(', ')']) == 'Yes'


def test_simple_open_close_pair_reversed_input_order():
    # order of concatenation is free, so [')','('] should still work
    # by concatenating second + first = '()'
    assert match_parens([')', '(']) == 'Yes'


def test_nested_balanced_concatenation():
    assert match_parens(['((', '))']) == 'Yes'


def test_unequal_counts_returns_no():
    # 3 opens total vs 2 closes total -> impossible regardless of order
    assert match_parens(['(((', '))']) == 'No'


def test_equal_counts_but_both_orders_fail():
    # Each string is ')(' -> counts balance overall (2 opens, 2 closes)
    # but both concatenation orders start with ')' and go negative immediately
    assert match_parens([')(', ')(']) == 'No'


def test_only_one_order_works():
    # A = '())' (open=1, close=2), B = '(()' (open=2, close=1)
    # A+B = '())(()' fails (goes negative early)
    # B+A = '(()())' succeeds
    assert match_parens(['())', '(()']) == 'Yes'


def test_all_closes_returns_no():
    assert match_parens([')))', ')))']) == 'No'


def test_all_opens_returns_no():
    assert match_parens(['(((', '(((']) == 'No'


def test_longer_balanced_strings():
    assert match_parens(['(()())', '()()()']) == 'Yes'


def test_single_char_each_mismatched_totally():
    assert match_parens(['(', '(']) == 'No'
